// C++ Standard Library (std::thread)
auto task = []() {
    // Thread specific work
    int result = 42;
    (void)result;
};

// Start execution in a new thread
std::thread worker(task);

// Parent thread waits for child to complete
if (worker.joinable()) {
    worker.join();
}
// Synchronization complete; memory is safe.
